{
  "items": [
    {
      "name": "Filter.Eventually.exists",
      "type": " {α : Type u} {p : α → Prop} {f : Filter α} [f.NeBot] (hp : ∀ᶠ (x : α) in f, p x) : ∃ x, p x",
      "module": "Mathlib.Order.Filter.Basic"
    },
    {
      "name": "Filter.frequently_iff_forall_eventually_exists_and",
      "type": " {α : Type u} {p : α → Prop} {f : Filter α} : (∃ᶠ (x : α) in f, p x) ↔ ∀ {q : α → Prop}, (∀ᶠ (x : α) in f, q x) → ∃ x, p x ∧ q x",
      "module": "Mathlib.Order.Filter.Basic"
    },
    {
      "name": "Filter.Eventually.choice",
      "type": " {α : Type u} {β : Type v} {r : α → β → Prop} {l : Filter α} [l.NeBot] (h : ∀ᶠ (x : α) in l, ∃ y, r x y) : ∃ f, ∀ᶠ (x : α) in l, r x (f x)",
      "module": "Mathlib.Order.Filter.Basic"
    },
    {
      "name": "Filter.Eventually.exists_mem",
      "type": " {α : Type u} {p : α → Prop} {f : Filter α} (hp : ∀ᶠ (x : α) in f, p x) : ∃ v ∈ f, ∀ y ∈ v, p y",
      "module": "Mathlib.Order.Filter.Basic"
    },
    {
      "name": "Filter.eventually_iff_exists_mem",
      "type": " {α : Type u} {p : α → Prop} {f : Filter α} : (∀ᶠ (x : α) in f, p x) ↔ ∃ v ∈ f, ∀ y ∈ v, p y",
      "module": "Mathlib.Order.Filter.Basic"
    },
    {
      "name": "Filter.skolem",
      "type": " {ι : Type u_2} {α : ι → Type u_3} [∀ (i : ι), Nonempty (α i)] {P : (i : ι) → α i → Prop} {F : Filter ι} : (∀ᶠ (i : ι) in F, ∃ b, P i b) ↔ ∃ b, ∀ᶠ (i : ι) in F, P i (b i)",
      "module": "Mathlib.Order.Filter.Basic"
    }
  ]
}
